// src/mcp.ts
var SESSION_ID_META_KEY = "ai.opencode/sessionID";
var PROTOCOL_VERSION = "2025-11-25";
var RECONNECT_MIN = 500;
var RECONNECT_MAX = 1e4;
function connectClientMcp(options) {
  const state = {
    disposed: false,
    delay: RECONNECT_MIN
  };
  const connect = () => {
    if (state.disposed)
      return;
    const Socket = options.WebSocket ?? WebSocket;
    const socket = options.headers ? new Socket(endpoint(options), { headers: options.headers }) : new Socket(endpoint(options));
    state.socket = socket;
    socket.addEventListener("message", (event) => {
      if (state.disposed || typeof event.data !== "string")
        return;
      const message = parse(event.data);
      if (!message)
        return;
      if (message.method === "notifications/initialized")
        state.delay = RECONNECT_MIN;
      if (typeof message.id !== "string" && typeof message.id !== "number" || typeof message.method !== "string")
        return;
      respond(options, message.method, message.params).then((reply) => send(socket, { jsonrpc: "2.0", id: message.id, ...reply }));
    });
    socket.addEventListener("close", () => {
      if (state.socket === socket)
        state.socket = undefined;
      if (state.disposed)
        return;
      state.timer = setTimeout(connect, state.delay);
      state.delay = Math.min(state.delay * 2, RECONNECT_MAX);
    });
  };
  connect();
  return {
    async close() {
      state.disposed = true;
      clearTimeout(state.timer);
      state.socket?.close(1000);
    }
  };
}
async function respond(options, method, params) {
  switch (method) {
    case "initialize":
      return {
        result: {
          protocolVersion: typeof params?.protocolVersion === "string" ? params.protocolVersion : PROTOCOL_VERSION,
          capabilities: { tools: {} },
          serverInfo: { name: options.name, version: "1.0.0" }
        }
      };
    case "ping":
      return { result: {} };
    case "tools/list":
      return {
        result: {
          tools: options.tools.map((tool) => ({
            name: tool.name,
            description: tool.description,
            inputSchema: { type: "object", ...tool.inputSchema }
          }))
        }
      };
    case "tools/call": {
      const tool = options.tools.find((tool) => tool.name === params?.name);
      if (!tool)
        return { error: { code: -32602, message: `Unknown tool: ${String(params?.name)}` } };
      const meta = params?._meta?.[SESSION_ID_META_KEY];
      return Promise.resolve().then(() => tool.handler(params?.arguments ?? {}, { sessionID: typeof meta === "string" ? meta : undefined })).then((result) => ({ result }), (error) => ({
        result: {
          content: [{ type: "text", text: error instanceof Error ? error.message : String(error) }],
          isError: true
        }
      }));
    }
  }
  return { error: { code: -32601, message: `Method not found: ${method}` } };
}
function send(socket, message) {
  if (socket.readyState === socket.OPEN)
    socket.send(JSON.stringify(message));
}
function parse(text) {
  try {
    const value = JSON.parse(text);
    return typeof value === "object" && value !== null && !Array.isArray(value) ? value : undefined;
  } catch {
    return;
  }
}
function endpoint(options) {
  const base = new URL(options.url);
  if (!base.pathname.endsWith("/"))
    base.pathname += "/";
  const url = new URL("api/experimental/client-mcp", base);
  url.search = base.search;
  if (options.directory)
    url.searchParams.set("location[directory]", options.directory);
  url.searchParams.set("name", options.name);
  url.protocol = url.protocol === "https:" || url.protocol === "wss:" ? "wss:" : "ws:";
  return url;
}
export {
  connectClientMcp
};
